// CRITICAL CAVEAT for Lucifer's Diary:
// frontend/components/TagBar.tsx uses <Link href={`${basePath}?tagIds=${id}`}>, so a tag click triggers a
// full App Router navigation. The card list on /browse, /search, /tag/[slug] is rendered server-side
// from new searchParams — the DOM tree for the cards is REPLACED, not mutated. Flip.getState captures
// nodes by reference; after the navigation those node refs are gone, so the verbatim demo pattern
// CANNOT survive the navigation as-is. You have three escape hatches:
//
// (A) [RECOMMENDED] Client-side filter on already-fetched data. Convert the cards container to a
//     client component that receives the full result set once, then filter in memory off URL state.
//     Keeps SSR-friendly URLs while letting the same DOM nodes persist across filter changes.
//
// (B) Bridge Flip across the navigation with sessionStorage. Snapshot Flip.getState() into
//     Flip.getState(items).clone()/JSON before router.push, then on the next render call
//     Flip.from(restoredState, {...}) inside useLayoutEffect. Works but is fragile — server-rendered
//     nodes must carry stable data-flip-id matching the snapshot ids.
//
// (C) Intercept the click, animate first, then navigate. Run updateFilters() locally (mutating display
//     on the current cards), then router.push the new URL after the tween completes. The new server
//     render then "lands" silently on top of the already-correct visual state.
//
// Below: pattern (A), the canonical Flip + useGSAP recipe. Hook it into a client-side <CardGrid>
// that owns the full data set and reads activeIds from useSearchParams. Tag clicks update the URL
// (so back/forward + sharable links keep working), but the cards never unmount.

"use client";
import { useRef } from "react";
import { useSearchParams } from "next/navigation";
import gsap from "gsap";
import { Flip } from "gsap/Flip";
import { useGSAP } from "@gsap/react";

gsap.registerPlugin(Flip, useGSAP);

export function CardGrid({ allCards }: { allCards: Card[] }) {
  const containerRef = useRef<HTMLDivElement>(null);
  const params = useSearchParams();
  const activeTagIds = params.get("tagIds")?.split(",").filter(Boolean) ?? [];

  // visibility map drives both render output AND the Flip mutation
  const visible = (c: Card) =>
    activeTagIds.length === 0 || c.tags.some((t) => activeTagIds.includes(t.id));

  // useGSAP with a dependency on activeTagIds runs Flip on EVERY filter change.
  // contextSafe + revertOnUpdate cleans up tweens between renders so rapid
  // clicks don't stack conflicting animations on the same nodes.
  useGSAP(
    () => {
      const items = gsap.utils.toArray<HTMLElement>(".card", containerRef.current);
      if (!items.length) return;

      // BEFORE-state snapshot — this is the LAYOUT-EFFECT moment: useGSAP runs after
      // the DOM has the NEW visibility classes applied by React's render, so we
      // need to snapshot from the *previous* render. The trick: snapshot inside a
      // useGSAP "dependencies" run BEFORE you mutate display. The cleanest way is
      // to snapshot synchronously in a ref before the re-render, then animate from it.
      // See pattern in https://gsap.com/docs/v3/Plugins/Flip/static.getState() — for React,
      // you typically snapshot in a useLayoutEffect that runs BEFORE the commit, OR
      // toggle a class instead of unmounting so the same nodes survive across renders.
      Flip.from(stateRef.current, {
        duration: 0.7,
        scale: true,
        ease: "power1.inOut",
        stagger: 0.08,
        absolute: true,
        onEnter: (els) =>
          gsap.fromTo(els, { opacity: 0, scale: 0 }, { opacity: 1, scale: 1, duration: 0.7 }),
        onLeave: (els) => gsap.to(els, { opacity: 0, scale: 0, duration: 0.7 }),
      });
    },
    { scope: containerRef, dependencies: [activeTagIds.join(",")] }
  );

  // Render ALL cards every time, just toggle a .is-hidden class (display:none in CSS)
  // so DOM nodes persist across filter changes and Flip can match them by ref.
  return (
    <div ref={containerRef} className="card-grid">
      {allCards.map((c) => (
        <article
          key={c.id}
          data-flip-id={c.id}                       /* stable identity for Flip */
          className={`card ${visible(c) ? "" : "is-hidden"}`}
        >
          {/* card content */}
        </article>
      ))}
    </div>
  );
}

// The CSS half:
// .card.is-hidden { display: none; }
//
// The "snapshot BEFORE mutation" half (omitted above for brevity):
//   Wrap the visibility toggle in a custom hook that does
//   Flip.getState(items) synchronously in a useLayoutEffect that fires BEFORE
//   React commits the new className. The GSAP team's official recipe for this is:
//     1. On tag click: setState({snapshot: Flip.getState(items), nextActive: ids})
//     2. In render: apply the .is-hidden class based on nextActive
//     3. In useGSAP with dep on nextActive: Flip.from(snapshot, {...}) — this runs
//        after commit so the DOM is already in the new flex layout.
//   This pattern is documented at https://gsap.com/docs/v3/Plugins/Flip/#react .
